export function getAuditCohortSummary() {
  const total = LONGITUDINAL_CLINICAL_AUDIT_DATASET.length;
  const complications = LONGITUDINAL_CLINICAL_AUDIT_DATASET.filter(r => r.postProcedureComplicationFlag).length;
  const readmissions = LONGITUDINAL_CLINICAL_AUDIT_DATASET.filter(r => r.readmissionWithin30Days).length;
  return {
    totalAuditedEncounters: total,
    complicationRatePercent: ((complications / total) * 100).toFixed(2),
    readmissionRatePercent: ((readmissions / total) * 100).toFixed(2)
  };
}
